+    public static String normalizeStatementDate(String value) {
+        if (!value) {
+            return value
+        }
+        Matcher matcher = (value.trim() =~ /^([0-3]?\d)\s*-?\s*([A-Za-z]{3,4})\s*-?\s*(\d{2,4})$/)
+        if (!matcher.matches()) {
+            return value.trim()
+        }
+        String month = matcher.group(2).toUpperCase().replace("JUY", "JUL")
+        "${matcher.group(1)}-${month}-${matcher.group(3)}"
+    }
+
+    private static Date parseStatementDate(String value) {
+        String normalizedDate = processValue(value)
+        SimpleDateFormat dateFormat = dateFormatFromString(normalizedDate)
+        if (!dateFormat) {
+            return null
+        }
+        dateFormat.setLenient(false)
+        dateFormat.parse(normalizedDate)
+    }
