+    private static void addHTMLTransaction(ProcessedBankStatementVO processedBankStatementVO,
+                                           BankTransactionHeaderIndex index, Map transaction) {
+        Date transactionDate = transaction.date as Date
+        if (!transactionDate) {
+            return
+        }
+        BankTransactionResponse response = new BankTransactionResponse()
+        response.transactionDate = transactionDate
+        response.valueDate = transaction.valueDate as Date
+        response.description = transaction.description?.toString()?.trim() ?: ""
+        response.remark = transaction.remark?.toString()?.trim() ?: ""
+        response.balanceAfterTransaction = transaction.balance ? BankUtil.processBalanceAmount(transaction.balance.toString()) : null
+
+        if (transaction.debit && !transaction.debit.toString().find("^[\\s]*(-[\\s]*)?\$")) {
+            response.amount = HelperMethod.getSanitizeDouble(transaction.debit.toString())
+            response.type = Enums.BankTransactionType.DEBIT
+        } else if (transaction.credit && !transaction.credit.toString().find("^[\\s]*(-[\\s]*)?\$")) {
+            response.amount = HelperMethod.getSanitizeDouble(transaction.credit.toString())
+            response.type = Enums.BankTransactionType.CREDIT
+        } else if (transaction.amount) {
+            response.amount = HelperMethod.getSanitizeDouble(transaction.amount.toString())
+        }
+        if (transaction.amountType) {
+            response.type = transaction.amountType.toString().toLowerCase().find("cr") ?
+                    Enums.BankTransactionType.CREDIT : Enums.BankTransactionType.DEBIT
+        }
+        processedBankStatementVO.bankTransactionList << response
+    }
